    machines_post_enroll: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description The machine's Ed25519 public key, base64url without padding. */
                    public_key: string;
                    name: string;
                    /**
                     * @description SPEC-098 FR-15…FR-18. A pre-auth key the owner minted
                     *     (`airdress_mk_…`). Redeeming one counts a use and skips the
                     *     anonymous pending cap. When the key is pre-approved, the
                     *     enrollment is approved at once with the key's grants, and the
                     *     first valid poll answers the machine id. Every refusal of
                     *     the key answers the same `401 access_denied`.
                     */
                    preauth_key?: string;
                    /**
                     * @description SPEC-098 G-2 (SPEC-116). What the machine enrolls for: shown
                     *     to the owner, and deciding what an approval may also link
                     *     it as (`home-assistant` → a `Home`, `thing` → a `Thing`,
                     *     SPEC-120). Absent for a plain machine; anything outside the
                     *     list is `400 invalid_request`.
                     * @enum {string}
                     */
                    purpose?: "home-assistant" | "thing";
                    /**
                     * @description SPEC-120 FR-32. What a thing announces about itself, only
                     *     with `purpose: thing`: shown to the owner verbatim before
                     *     approval, and what an approval's link declares. Names match
                     *     `[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?`; at most 32 events and
                     *     32 commands; `board`, `sdk` and `firmware` 1–64 characters.
                     *     Out of bounds, or without the purpose, is `400 invalid_request`.
                     */
                    thing?: {
                        board?: string;
                        sdk?: string;
                        firmware?: string;
                        events?: string[];
                        commands?: string[];
                    };
                };
            };
        };
        responses: {
            /** @description The enrollment. Show the owner `user_code` and `fingerprint`. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        device_code: string;
                        /** @example WDJB-MJHT */
                        user_code: string;
                        /** @example 600 */
                        expires_in: number;
                        /** @example 5 */
                        interval: number;
                        /** @example SHA256:47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFU */
                        fingerprint: string;
                        /**
                         * Format: uri
                         * @description SPEC-098 FR-23. Where the owner approves; present when the operator knows its public origin.
                         */
                        verification_uri?: string;
                        /**
                         * Format: uri
                         * @description The same, naming this `user_code`. Still show the user code (RFC 8628 §3.3.1).
                         */
                        verification_uri_complete?: string;
                        /** @description SPEC-098 FR-30. The key this operator signed the answer with. */
                        operator_key?: {
                            kid: string;
                            /** @description Ed25519, base64url without padding. */
                            public_key: string;
                        };
                        /**
                         * @description Ed25519 signature by `operator_key`, base64url, over
                         *     `airdress-machine-enroll-answer-v1\0`, the operator's
                         *     origin, 0x1F, `user_code`, 0x1F and the machine's public
                         *     key. The machine verifies it and shows the confirmation
                         *     code: SHA-256 of `airdress-machine-confirm-v1\0`, the
                         *     operator key, the machine key and `user_code`, first 100
                         *     bits in base32, five groups of four.
                         */
                        operator_proof?: string;
                    };
                };
            };
            /** @description A malformed body, key or name (`invalid_request`). */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["MachineEnrollmentError"];
                };
            };
            /**
             * @description The pre-auth key was not accepted (`access_denied`): unknown, wrong,
             *     expired, revoked or used up. The answer does not say which.
             */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["MachineEnrollmentError"];
                };
            };
            /** @description The pre-auth key's grants no longer apply (`grant_template_invalid`). */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["MachineEnrollmentError"];
                };
            };
            /** @description Too many enrollments from this network, or pending on this operator. */
            429: {
                headers: {
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["MachineEnrollmentError"];
                };
            };
        };
    };
